from decimal import Decimal, InvalidOperation


def _value(source: dict | None, key: str) -> object:
    if not source:
        return ""
    value = source.get(key, "")
    return "" if value is None else value


def _number(value: object) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _date_equal(value: object, literal: str) -> bool:
    return str(value) == literal


def _date_greater_equal(value: object, other: str) -> bool:
    value = str(value)
    if value == "00000000" or other == "00000000":
        return False
    return value >= other


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    stat_cd = _value(record, "STAT_CD")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    amount = _number(_value(record, "AMT"))
    stage_pct = _number(_value(record, "STAGE_PCT"))

    def add_error(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    if event in ("INSERT", "UPDATE"):
        if not (amount >= Decimal(0)):
            add_error("E3001", "Amount negative")

    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and amount == Decimal(0))):
            add_error("E3002", "Won opportunity requires amount")

    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_rsn == "")):
            add_error("E3003", "Lost reason required")

    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _date_equal(close_dt, "00000000"))):
            add_error("E3004", "Won opportunity requires close date")

    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            add_error("E3005", "Cannot reopen a won opportunity")

    if event in ("INSERT", "UPDATE"):
        stage_consistent = (
            (stat_cd == "P" and stage_pct == Decimal(10))
            or (stat_cd == "Q" and stage_pct == Decimal(25))
            or (stat_cd == "N" and stage_pct == Decimal(60))
            or (stat_cd == "W" and stage_pct == Decimal(100))
            or (stat_cd == "L" and stage_pct == Decimal(0))
        )
        if not stage_consistent:
            add_error("E3006", "Stage percent inconsistent with status")

    if event == "INSERT":
        close_date_valid = _date_equal(close_dt, "00000000") or _date_greater_equal(
            close_dt, today
        )
        if not close_date_valid:
            add_error("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
